    vector<int> lastVisitedCell(vector<vector<char>>& grid) {
        int m = grid.size(), n = grid[0].size();
        int r = 0, c = 0;
        vector<vector<bool>> vis(m, vector<bool>(n));
        while (true) {
            vector<int> cur = {r, c};
            vis[r][c] = true;
            switch (grid[r][c]) {
            case 'L': c--; break;
            case 'R': c++; break;
            case 'U': r--; break;
            case 'D': r++; break;
            }
            if (r >= 0 && r < m && c >= 0 && c < n && !vis[r][c]) {
                continue;
            }
            return cur;
        }
    }
};

func lastVisitedCell(grid [][]byte) []int {
	m, n := len(grid), len(grid[0])
	r, c := 0, 0
	vis := make([][]bool, m)
	for i := range vis {
		vis[i] = make([]bool, n)
	}
	for {
		cur := []int{r, c}
		vis[r][c] = true
		switch grid[r][c] {
		case 'L':
			c--
		case 'R':
			c++
		case 'U':
			r--
		case 'D':
			r++
		}
		if r >= 0 && r < m && c >= 0 && c < n && !vis[r][c] {
			continue
		}
		return cur
	}
}

function lastVisitedCell(grid: string[][]): number[] {
    const m = grid.length,
        n = grid[0].length;
    let r = 0,
        c = 0;
    const vis = Array.from({ length: m }, () => Array(n).fill(false));
    while (true) {
        const cur = [r, c];
        vis[r][c] = true;
        switch (grid[r][c]) {
            case 'L':
                c--;
                break;
            case 'R':
                c++;
                break;
            case 'U':
                r--;
                break;
            case 'D':
                r++;
                break;
        }
        if (r >= 0 && r < m && c >= 0 && c < n && !vis[r][c]) {
            continue;
        }
        return cur;
    }
}
